  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `garage_id` int(10) unsigned DEFAULT NULL,
  `speed` smallint(5) unsigned DEFAULT NULL,
  `acceleration` smallint(5) unsigned DEFAULT NULL,
  `handling` smallint(5) unsigned DEFAULT NULL,
  `nitro` smallint(5) unsigned DEFAULT NULL,
  `mark` smallint(5) unsigned DEFAULT NULL,
  `division` smallint(5) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UNIQ_F5DB9824C4FFF555` (`garage_id`),
  KEY `garage_gauntlet_idx` (`id`),
  CONSTRAINT `FK_F5DB9824C4FFF555` FOREIGN KEY (`garage_id`) REFERENCES `garage_app` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=339 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
