DROP TABLE IF EXISTS `garage_stat_actual`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `garage_stat_actual` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `garage_id` int(10) unsigned DEFAULT NULL,
  `speed` double NOT NULL,
  `acceleration` double NOT NULL,
  `handling` double NOT NULL,
  `nitro` double NOT NULL,
  `average` double NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UNIQ_3FDFA9D8C4FFF555` (`garage_id`),
  KEY `garage_stat_actual_idx` (`id`),
  CONSTRAINT `FK_3FDFA9D8C4FFF555` FOREIGN KEY (`garage_id`) REFERENCES `garage_app` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=339 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
