  `speed` double NOT NULL,
  `acceleration` double NOT NULL,
  `handling` double NOT NULL,
  `nitro` double NOT NULL,
  `average` double NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UNIQ_91F01015C4FFF555` (`garage_id`),
  KEY `garage_stat_max_idx` (`id`),
  CONSTRAINT `FK_91F01015C4FFF555` FOREIGN KEY (`garage_id`) REFERENCES `garage_app` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=339 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
