  `garage_id` int(10) unsigned DEFAULT NULL,
  `unblock` tinyint(4) NOT NULL,
  `gold` tinyint(4) NOT NULL,
  `to_upgrade` tinyint(4) NOT NULL,
  `evo` tinyint(4) NOT NULL,
  `event_class` tinyint(4) NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UNIQ_E83E21CCC4FFF555` (`garage_id`),
  KEY `garage_status_idx` (`id`),
  CONSTRAINT `FK_E83E21CCC4FFF555` FOREIGN KEY (`garage_id`) REFERENCES `garage_app` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=339 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
